begin;

-- Tracks requisition documents generated by this app and imported into ERP.
-- ERP is the source of truth for inventory, but this table preserves export intent + reconciliation metadata.

create table if not exists public.production_requisition_exports (
  doc_ref text primary key,
  master_plan_no text references public.production_master_plans(master_plan_no) on delete set null,
  sub_plan_no text references public.production_sub_plans(sub_plan_no) on delete set null,
  department_id uuid references public.production_departments(id) on delete set null,
  export_mode text not null default 'weekly',
  date_from date,
  date_to date,
  status text not null default 'draft',
  exported_at timestamptz,
  exported_by uuid references public.profiles(id) on delete set null,
  exported_by_name text,
  erp_last_synced_at timestamptz,
  erp_hash text,
  reconcile_result jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid references public.profiles(id) on delete set null,
  updated_by uuid references public.profiles(id) on delete set null,
  constraint production_requisition_exports_status_check
    check (status in ('draft','exported','imported','erp_changed','closed','cancelled')),
  constraint production_requisition_exports_export_mode_check
    check (export_mode in ('weekly','daily'))
);

create index if not exists production_requisition_exports_master_idx
  on public.production_requisition_exports (master_plan_no, status, exported_at desc);

create index if not exists production_requisition_exports_dept_idx
  on public.production_requisition_exports (department_id, status, exported_at desc);

drop trigger if exists production_requisition_exports_set_updated_at on public.production_requisition_exports;
create trigger production_requisition_exports_set_updated_at
  before update on public.production_requisition_exports
  for each row execute procedure public.set_updated_at();

create table if not exists public.production_requisition_export_lines (
  doc_ref text not null references public.production_requisition_exports(doc_ref) on delete cascade,
  line_seq integer not null,
  sku_code text not null,
  sku_name text,
  qty numeric not null default 0,
  uom text,
  lot_no text,
  warehouse_code text,
  remark text,
  meta jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint production_requisition_export_lines_pkey primary key (doc_ref, line_seq),
  constraint production_requisition_export_lines_qty_check check (qty >= 0)
);

create index if not exists production_requisition_export_lines_sku_idx
  on public.production_requisition_export_lines (sku_code);

drop trigger if exists production_requisition_export_lines_set_updated_at on public.production_requisition_export_lines;
create trigger production_requisition_export_lines_set_updated_at
  before update on public.production_requisition_export_lines
  for each row execute procedure public.set_updated_at();

alter table public.production_requisition_exports enable row level security;
alter table public.production_requisition_export_lines enable row level security;

-- Read access: planning viewers can see exports and reconcile status.
drop policy if exists production_requisition_exports_read on public.production_requisition_exports;
create policy production_requisition_exports_read
  on public.production_requisition_exports
  for select
  to authenticated
  using (
    public.is_admin()
    or public.has_permission('production-line-planning-view')
    or public.has_permission('production-line-planning-manage')
    or public.has_permission('plan.view_all')
    or public.has_permission('plan.edit_own_dept')
  );

-- Write access: planning managers/editors produce exports.
drop policy if exists production_requisition_exports_write on public.production_requisition_exports;
create policy production_requisition_exports_write
  on public.production_requisition_exports
  for all
  to authenticated
  using (
    public.is_admin()
    or public.has_permission('production-line-planning-manage')
    or public.has_permission('plan.edit_own_dept')
  )
  with check (
    public.is_admin()
    or public.has_permission('production-line-planning-manage')
    or public.has_permission('plan.edit_own_dept')
  );

drop policy if exists production_requisition_export_lines_read on public.production_requisition_export_lines;
create policy production_requisition_export_lines_read
  on public.production_requisition_export_lines
  for select
  to authenticated
  using (
    public.is_admin()
    or public.has_permission('production-line-planning-view')
    or public.has_permission('production-line-planning-manage')
    or public.has_permission('plan.view_all')
    or public.has_permission('plan.edit_own_dept')
  );

drop policy if exists production_requisition_export_lines_write on public.production_requisition_export_lines;
create policy production_requisition_export_lines_write
  on public.production_requisition_export_lines
  for all
  to authenticated
  using (
    public.is_admin()
    or public.has_permission('production-line-planning-manage')
    or public.has_permission('plan.edit_own_dept')
  )
  with check (
    public.is_admin()
    or public.has_permission('production-line-planning-manage')
    or public.has_permission('plan.edit_own_dept')
  );

commit;

